const state={view:'research',runs:[],research:null,reviews:[],audit:[],library:{q:'',owner:'ALL',status:'ALL',review:'ALL',sort:'updated_at',order:'desc'},reviewFilters:{severity:'ALL',status:'ALL'},auditFilters:{actor:'ALL',status:'ALL'}};
const main=document.querySelector('#main'),drawer=document.querySelector('#drawer'),drawerTitle=document.querySelector('#drawer-title'),drawerEyebrow=document.querySelector('#drawer-eyebrow'),drawerBody=document.querySelector('#drawer-body'),scrim=document.querySelector('#scrim');
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt=d=>d?new Intl.DateTimeFormat('en',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(d)):'—';
const status=s=>`<span class="status ${esc(s)}">${esc(String(s).replaceAll('_',' '))}</span>`;
const pill=(text,kind='')=>`<span class="pill ${kind}">${esc(text)}</span>`;
async function load(){main.innerHTML='<div class="loading">Loading fixture workspace…</div>';const [runs,research,reviews,audit]=await Promise.all(['../fixtures/v0/runs.json','../fixtures/v0/research-main.json','../fixtures/v0/reviews.json','../fixtures/v0/audit.json'].map(u=>fetch(u).then(r=>{if(!r.ok)throw new Error(u);return r.json()})));Object.assign(state,{runs,research,reviews,audit});render();}
function setView(view){state.view=view;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.view===view));closeDrawer();render();}
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
document.querySelector('#drawer-close').addEventListener('click',closeDrawer);scrim.addEventListener('click',closeDrawer);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});
function openDrawer(title,eyebrow,html){drawerTitle.textContent=title;drawerEyebrow.textContent=eyebrow;drawerBody.innerHTML=html;drawer.classList.add('open');scrim.classList.add('show');drawer.setAttribute('aria-hidden','false')}
function closeDrawer(){drawer.classList.remove('open');scrim.classList.remove('show');drawer.setAttribute('aria-hidden','true')}
function render(){({research:renderResearch,library:renderLibrary,reviews:renderReviews,audit:renderAudit}[state.view]||renderResearch)()}
function renderResearch(){const r=state.research.run,a=r.assurance_summary;main.innerHTML=`<section class="page-head"><div><div class="eyebrow">Research / ${esc(r.id)}</div><h1>${esc(r.title)}</h1><div class="lede">${esc(r.question)}</div><div class="topics">${r.topics.map(t=>pill(t)).join('')}</div><div class="summary-row">${pill(`${a.verified} verified`,'good')}${pill(`${a.disputed} disputed`,'bad')}${pill(`${a.unverified} unverified`,'warn')}${pill(`${a.inference} inference`)}${pill(`${a.independent_roots} evidence roots`)}</div></div><div class="meta-actions"><button class="ghost" id="show-claims">Claims</button><button class="ghost" id="show-sources">Sources</button></div></section><article class="card report">${state.research.report_sections.map(sec=>`<section class="report-section"><h2>${esc(sec.heading)}</h2><p>${esc(sec.text)} ${sec.claim_ids.map(id=>`<button class="cite" data-claim="${id}">${esc(id.replace('clm_','C'))}</button>`).join('')}</p></section>`).join('')}</article><h2 class="section-title">Discussion</h2><section class="card comments" id="comments">${state.research.comments.map(c=>commentHtml(c)).join('')}<form class="comment-form" id="comment-form"><input name="body" placeholder="Comment on this research version…" autocomplete="off"/><button class="button">Add comment</button></form></section>`;
main.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>inspectClaim(b.dataset.claim));document.querySelector('#show-claims').onclick=showClaims;document.querySelector('#show-sources').onclick=showSources;document.querySelector('#comment-form').onsubmit=e=>{e.preventDefault();const input=e.currentTarget.body;if(!input.value.trim())return;state.research.comments.push({id:`local_${Date.now()}`,author:'Maya Chen',parent_type:'DOCUMENT_VERSION',parent_id:r.current_document_version_id,body:input.value.trim(),created_at:new Date().toISOString(),resolved_at:null});renderResearch()}}
function commentHtml(c){return `<div class="comment"><div class="comment-meta"><span>${esc(c.author)} · ${esc(c.parent_type.replaceAll('_',' ').toLowerCase())}</span><span>${fmt(c.created_at)}</span></div><p>${esc(c.body)}</p></div>`}
function inspectClaim(id){const c=state.research.claims.find(x=>x.id===id);if(!c)return;const edges=state.research.claim_evidence.filter(x=>x.claim_id===id);const evidence=edges.map(edge=>({edge,ev:state.research.evidence_spans.find(e=>e.id===edge.evidence_span_id)})).filter(x=>x.ev);openDrawer(c.normalized_text,'Claim inspector',`<div class="detail-block"><h3>State</h3>${status(c.state)}<p style="margin-top:10px">${esc(c.verification_summary)}</p></div><div class="detail-block"><h3>Original claim</h3><p>${esc(c.text)}</p></div><div class="detail-block"><h3>Claim IR</h3><div class="kv">${Object.entries(c.ir||{}).map(([k,v])=>`<div>${esc(k)}</div><div><code>${esc(Array.isArray(v)?v.join(', '):(v===null?'unknown':v))}</code></div>`).join('')}</div></div>${evidence.length?evidence.map(({edge,ev})=>{const src=state.research.source_versions.find(s=>s.id===ev.source_version_id);return `<div class="detail-block"><h3>${esc(edge.relation)} · ${esc(src?.title||ev.source_version_id)}</h3><p class="quote">${esc(ev.canonical_excerpt)}</p><div class="subtle" style="margin-top:9px">${esc(ev.locator)}</div><button class="ghost" style="margin-top:12px" data-source="${ev.source_version_id}">Source version</button></div>`}).join(''):'<div class="detail-block"><p>No registered evidence in this fixture.</p></div>'}`);drawerBody.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>inspectSource(b.dataset.source))}
function inspectSource(id){const s=state.research.source_versions.find(x=>x.id===id);if(!s)return;openDrawer(s.title,'Source version',`<div class="detail-block"><h3>Identity</h3><div class="kv"><div>Publisher</div><div>${esc(s.publisher)}</div><div>Type</div><div>${esc(s.source_type)}</div><div>Retrieved</div><div>${fmt(s.retrieved_at)}</div><div>Published</div><div>${esc(s.published_at||'unknown')}</div></div></div><div class="detail-block"><h3>Lineage</h3><p>${esc(s.lineage_summary||'Unknown')}</p></div><div class="detail-block"><h3>Machine identity</h3><div class="kv"><div>Artifact</div><div><code>${esc(s.artifact_hash)}</code></div><div>Extraction</div><div><code>${esc(s.canonical_extraction_hash)}</code></div><div>Parser</div><div><code>${esc(s.parser_version)}</code></div></div></div>`)}
function showClaims(){openDrawer('Claims','Research projection',`<div class="claim-list">${state.research.claims.map(c=>`<div class="claim-row" data-inspect="${c.id}"><div class="claim-state">${status(c.state)}</div><div class="claim-text">${esc(c.normalized_text)}</div><div class="subtle">${esc(c.claim_type)}</div></div>`).join('')}</div>`);drawerBody.querySelectorAll('[data-inspect]').forEach(x=>x.onclick=()=>inspectClaim(x.dataset.inspect))}
function showSources(){openDrawer('Sources','Research projection',state.research.source_versions.map(s=>`<div class="detail-block" data-source-row="${s.id}" style="cursor:pointer"><h3>${esc(s.source_type)}</h3><p>${esc(s.title)}</p><div class="subtle">${esc(s.publisher)} · ${esc(s.lineage_summary)}</div></div>`).join(''));drawerBody.querySelectorAll('[data-source-row]').forEach(x=>x.onclick=()=>inspectSource(x.dataset.sourceRow))}
function unique(key){return ['ALL',...new Set(state.runs.map(r=>r[key]).filter(Boolean))]}
function options(vals,current){return vals.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v.replaceAll('_',' '))}</option>`).join('')}
function renderLibrary(){const f=state.library;let rows=state.runs.filter(r=>(!f.q||`${r.title} ${r.question_excerpt} ${r.topics.join(' ')}`.toLowerCase().includes(f.q.toLowerCase()))&&(f.owner==='ALL'||r.owner===f.owner)&&(f.status==='ALL'||r.status===f.status)&&(f.review==='ALL'||r.review_state===f.review));rows.sort((a,b)=>{let x=a[f.sort]??'',y=b[f.sort]??'';return (x<y?-1:x>y?1:0)*(f.order==='asc'?1:-1)});main.innerHTML=`<section class="page-head"><div><div class="eyebrow">Library</div><h1>Research library</h1><div class="lede">Find your work and authorized teammate research. Sort and filter without changing research identity.</div></div></section><div class="toolbar"><input class="control search" id="lib-q" placeholder="Search research…" value="${esc(f.q)}"><select class="control" id="lib-owner">${options(unique('owner'),f.owner)}</select><select class="control" id="lib-status">${options(['ALL','COMPLETE','IN_PROGRESS'],f.status)}</select><select class="control" id="lib-review">${options(['ALL','PENDING','APPROVED','CHANGES_REQUESTED','NOT_REQUESTED'],f.review)}</select><button class="button" id="lib-order">${f.sort.replaceAll('_',' ')} ${f.order==='asc'?'↑':'↓'}</button></div><div class="table-wrap"><table><thead><tr><th>Research</th><th>Owner</th><th>Status</th><th>Review</th><th>Claims</th><th>Updated</th></tr></thead><tbody>${rows.map(r=>`<tr data-run="${r.id}"><td><div class="title-cell">${esc(r.title)}</div><div class="subtle">${esc(r.topics.join(' · '))}</div></td><td>${esc(r.owner)}</td><td>${status(r.status)}</td><td>${status(r.review_state)}</td><td>${r.claim_counts.verified}V · ${r.claim_counts.disputed}D</td><td>${fmt(r.updated_at)}</td></tr>`).join('')}</tbody></table></div>`;document.querySelector('#lib-q').oninput=e=>{f.q=e.target.value;renderLibrary()};document.querySelector('#lib-owner').onchange=e=>{f.owner=e.target.value;renderLibrary()};document.querySelector('#lib-status').onchange=e=>{f.status=e.target.value;renderLibrary()};document.querySelector('#lib-review').onchange=e=>{f.review=e.target.value;renderLibrary()};document.querySelector('#lib-order').onclick=()=>{f.order=f.order==='asc'?'desc':'asc';renderLibrary()};main.querySelectorAll('[data-run]').forEach(row=>row.onclick=()=>{const id=row.dataset.run;if(id==='run_grid_001')setView('research');else openDrawer(state.runs.find(r=>r.id===id).title,'Fixture run',`<div class="detail-block"><p>This row proves Library discovery and stable run identity. Only the primary fixture has a full research dossier in v0.</p></div><div class="detail-block"><h3>Run ID</h3><code>${esc(id)}</code></div>`)})}
function renderReviews(){const f=state.reviewFilters;let rows=state.reviews.filter(r=>(f.severity==='ALL'||r.severity===f.severity)&&(f.status==='ALL'||r.review_state===f.status));main.innerHTML=`<section class="page-head"><div><div class="eyebrow">Reviews</div><h1>Review queue</h1><div class="lede">Start with the riskiest claims and exact document versions, not a generic inbox.</div></div></section><div class="toolbar" style="grid-template-columns:200px 220px 1fr"><select class="control" id="rev-severity">${options(['ALL','HIGH','LOW'],f.severity)}</select><select class="control" id="rev-status">${options(['ALL','OPEN','CHANGES_REQUESTED','APPROVED'],f.status)}</select></div><div class="table-wrap"><table><thead><tr><th>Severity</th><th>Research</th><th>Risk reason</th><th>Owner</th><th>State</th><th>Updated</th></tr></thead><tbody>${rows.map(r=>`<tr data-review="${r.id}"><td>${status(r.severity)}</td><td class="title-cell">${esc(state.runs.find(x=>x.id===r.run_id)?.title||r.run_id)}<div class="subtle">${esc(r.document_version_id)}</div></td><td>${esc(r.risk_reason)}</td><td>${esc(r.owner)}</td><td>${status(r.review_state)}</td><td>${fmt(r.updated_at)}</td></tr>`).join('')}</tbody></table></div>`;document.querySelector('#rev-severity').onchange=e=>{f.severity=e.target.value;renderReviews()};document.querySelector('#rev-status').onchange=e=>{f.status=e.target.value;renderReviews()};main.querySelectorAll('[data-review]').forEach(row=>row.onclick=()=>{const r=state.reviews.find(x=>x.id===row.dataset.review);openDrawer(r.risk_reason,'Review finding',`<div class="detail-block"><h3>Bound version</h3><code>${esc(r.document_version_id)}</code></div><div class="detail-block"><h3>Finding</h3><p>${esc(r.finding)}</p></div>${r.primary_claim_id&&state.research.claims.some(c=>c.id===r.primary_claim_id)?`<button class="button" id="inspect-review-claim">Inspect ${esc(r.primary_claim_id)}</button>`:''}`);const b=document.querySelector('#inspect-review-claim');if(b)b.onclick=()=>inspectClaim(r.primary_claim_id)})}
function renderAudit(){const f=state.auditFilters;let rows=state.audit.filter(e=>(f.actor==='ALL'||e.actor_type===f.actor)&&(f.status==='ALL'||e.status===f.status));main.innerHTML=`<section class="page-head"><div><div class="eyebrow">Audit</div><h1>Research audit trail</h1><div class="lede">Readable event summaries first. Raw hashes, payloads, and component metadata stay behind inspection.</div></div></section><div class="toolbar" style="grid-template-columns:220px 220px 1fr"><select class="control" id="audit-actor">${options(['ALL','HUMAN','MODEL','SYSTEM','TOOL'],f.actor)}</select><select class="control" id="audit-status">${options(['ALL','SUCCESS','WARNING'],f.status)}</select></div><div class="table-wrap"><table><thead><tr><th>#</th><th>Actor</th><th>Event</th><th>Summary</th><th>Status</th><th>Time</th></tr></thead><tbody>${rows.map(e=>`<tr data-event="${e.id}"><td>${e.sequence}</td><td><div class="title-cell">${esc(e.actor_display)}</div><div class="subtle">${esc(e.actor_type)}</div></td><td>${esc(e.event_type.replaceAll('_',' '))}</td><td class="audit-summary">${esc(e.summary)}</td><td>${status(e.status)}</td><td>${fmt(e.created_at)}</td></tr>`).join('')}</tbody></table></div>`;document.querySelector('#audit-actor').onchange=e=>{f.actor=e.target.value;renderAudit()};document.querySelector('#audit-status').onchange=e=>{f.status=e.target.value;renderAudit()};main.querySelectorAll('[data-event]').forEach(row=>row.onclick=()=>inspectEvent(row.dataset.event))}
function inspectEvent(id){const e=state.audit.find(x=>x.id===id);openDrawer(e.event_type.replaceAll('_',' '),'Audit event',`<div class="detail-block"><h3>Summary</h3><p>${esc(e.summary)}</p></div><div class="detail-block"><h3>Activity</h3><div class="kv"><div>Actor</div><div>${esc(e.actor_display)} (${esc(e.actor_type)})</div><div>Component</div><div><code>${esc(e.component_version)}</code></div><div>Status</div><div>${status(e.status)}</div><div>Time</div><div>${fmt(e.created_at)}</div></div></div><div class="detail-block"><h3>Inputs</h3><code>${esc((e.input_refs||[]).join(', ')||'none')}</code></div><div class="detail-block"><h3>Outputs</h3><code>${esc((e.output_refs||[]).join(', ')||'none')}</code></div><div class="detail-block"><h3>Raw fixture payload</h3><pre><code>${esc(JSON.stringify(e.detail,null,2))}</code></pre></div>`)}
load().catch(err=>{console.error(err);main.innerHTML='<div class="empty">Could not load fixture JSON. Serve the repository over HTTP instead of opening index.html directly.</div>'});
